func buildSnap(t *testing.T, provRef providers.Reference) *deploy.Snapshot {
	s := &deploy.Snapshot{}
	prov := &resource.State{
		Type: "pulumi:providers:pkgA", URN: "urn:pulumi:test-stack::test-project::pulumi:providers:pkgA::prov",
		Custom: true, ID: "id-prov",
	}
	s.Resources = append(s.Resources, prov)
	resA := &resource.State{
		Type: "pkgA:index:Resource", URN: "urn:pulumi:test-stack::test-project::pkgA:index:Resource::resA",
		Custom: true, ID: "id-a", Provider: provRef.String(),
		Inputs:  resource.PropertyMap{},
		Outputs: resource.PropertyMap{"v": resource.NewProperty("old-a")},
	}
	s.Resources = append(s.Resources, resA)
	resB := &resource.State{
		Type: "pkgA:index:Resource", URN: "urn:pulumi:test-stack::test-project::pkgA:index:Resource::resB",
		Custom: true, ID: "id-b", Provider: provRef.String(),
		Inputs:  resource.PropertyMap{},
		Outputs: resource.PropertyMap{"v": resource.NewProperty("old-b")},
	}
	s.Resources = append(s.Resources, resB)
	require.NoError(t, s.VerifyIntegrity())
	return s
}

func runVerify(t *testing.T, opts engine.UpdateOptions) *deploy.Snapshot {
	p := &lt.TestPlan{Project: "test-project", Stack: "test-stack"}
	project := p.GetProject()

	prov := &resource.State{URN: "urn:pulumi:test-stack::test-project::pulumi:providers:pkgA::prov", ID: "id-prov"}
	provRef, err := providers.NewReference(prov.URN, prov.ID)
	require.NoError(t, err)
	snap := buildSnap(t, provRef)

	readF := func(_ context.Context, req plugin.ReadRequest) (plugin.ReadResponse, error) {
		return plugin.ReadResponse{
			ReadResult: plugin.ReadResult{
				ID:      req.ID,
				Inputs:  req.Inputs,
				Outputs: resource.PropertyMap{"v": resource.NewProperty("refreshed")},
			},
			Status: resource.StatusOK,
		}, nil
	}
	loaders := []*deploytest.ProviderLoader{
		deploytest.NewProviderLoader("pkgA", semver.MustParse("1.0.0"), func() (plugin.Provider, error) {
			return &deploytest.Provider{ReadF: readF}, nil
		}),
	}
	programF := deploytest.NewLanguageRuntimeF(func(_ plugin.RunInfo, monitor *deploytest.ResourceMonitor) error {
		p, err := monitor.RegisterResource("pulumi:providers:pkgA", "prov", true, deploytest.ResourceOptions{})
		require.NoError(t, err)
		pRef, err := providers.NewReference(p.URN, p.ID)
		require.NoError(t, err)
		_, err = monitor.RegisterResource("pkgA:index:Resource", "resA", true, deploytest.ResourceOptions{Provider: pRef.String()})
		require.NoError(t, err)
		_, err = monitor.RegisterResource("pkgA:index:Resource", "resB", true, deploytest.ResourceOptions{Provider: pRef.String()})
		require.NoError(t, err)
		return nil
	})
	hostF := deploytest.NewPluginHostF(nil, nil, programF, loaders...)
	to := lt.TestUpdateOptions{T: t, HostF: hostF, UpdateOptions: opts}
	newSnap, err := lt.TestOp(engine.RefreshV2).RunStep(project, p.GetTarget(t, snap), to, false, p.BackendClient, nil, "1")
	require.NoError(t, err)
	return newSnap
}

func outFor(snap *deploy.Snapshot, name string) string {
	for _, r := range snap.Resources {
		if r.URN.Name() == name {
			if v, ok := r.Outputs["v"]; ok {
				return v.StringValue()
			}
		}
	}
	return "<missing>"
}

func TestZZExclude(t *testing.T) {
	t.Parallel()
	snap := runVerify(t, engine.UpdateOptions{
		Excludes: deploy.NewUrnTargets([]string{"urn:pulumi:test-stack::test-project::pkgA:index:Resource::resB"}),
	})
	assert.Len(t, snap.Resources, 3, "count preserved")
	assert.Equal(t, "refreshed", outFor(snap, "resA"), "non-excluded refreshed")
	assert.Equal(t, "old-b", outFor(snap, "resB"), "excluded keeps old outputs")
}

func TestZZTarget(t *testing.T) {
	t.Parallel()
	snap := runVerify(t, engine.UpdateOptions{
		Targets: deploy.NewUrnTargets([]string{"urn:pulumi:test-stack::test-project::pkgA:index:Resource::resA"}),
	})
	assert.Len(t, snap.Resources, 3, "count preserved")
	assert.Equal(t, "refreshed", outFor(snap, "resA"), "targeted refreshed")
	assert.Equal(t, "old-b", outFor(snap, "resB"), "non-targeted keeps old outputs")
}
